import{_ as a,o as t,c as i,a5 as o}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Import templates and manage profiles","description":"","frontmatter":{"title":"Import templates and manage profiles","docId":"user.automations.templates","translationKey":"user.automations.templates","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e9847c93a8a75fd5a58cd115b49b8e0bcb091ceda1dbdf2c226b52667eb17e23","translationRevision":"e9847c93a8a75fd5a58cd115b49b8e0bcb091ceda1dbdf2c226b52667eb17e23","order":50},"headers":[],"relativePath":"en/user/automations/templates.md","filePath":"en/user/automations/templates.md","lastUpdated":1794611623000}'),r={name:"en/user/automations/templates.md"};function s(n,e,l,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="import-templates-and-manage-profiles" tabindex="-1">Import templates and manage profiles <a class="header-anchor" href="#import-templates-and-manage-profiles" aria-label="Permalink to &quot;Import templates and manage profiles {#import-templates-and-manage-profiles}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Reuse a reviewed rule or a collection of rules without activating effects accidentally. You need <strong>Automations</strong>, a trusted JSON file or catalog entry, and any plugins required by its actions. Export the current profile before replacing an established setup.</p><h2 id="choose-the-right-surface" tabindex="-1">Choose the right surface <a class="header-anchor" href="#choose-the-right-surface" aria-label="Permalink to &quot;Choose the right surface {#choose-the-right-surface}&quot;">​</a></h2><p>A <code>.tiktemplate.json</code> document describes one event and its actions. A <code>.tikprofile.json</code> document groups several templates. Open the templates dialog from Automations for built-in/custom templates, its Cloud library or manual template import. Use the profile toolbar for profile creation, selection, export and manual profile import. <strong>Plugins → Explore</strong> browses plugins; templates and profiles belong here.</p><h2 id="review-and-import" tabindex="-1">Review and import <a class="header-anchor" href="#review-and-import" aria-label="Permalink to &quot;Review and import {#review-and-import}&quot;">​</a></h2><ol><li>Open the intended import dialog and choose a file or paste supported JSON. Check the staged name and source before continuing.</li><li>For a template, inspect the trigger, action types and parameters. For a profile, also inspect the number of entries and any common parameters.</li><li>Replace example destinations, media paths and viewer identifiers with values appropriate to your own setup. Do not paste credentials into a file intended for sharing.</li><li>Apply/import explicitly and wait for the result. Do not assume imported definitions are disabled; inspect the reviewed enabled values. Select them afterward and review each action and event before explicitly enabling the ones you want.</li><li>Start with a log-only test or inspect definitions first. Tests of HTTP, audio, points or plugins can execute effects.</li><li>Before confirming a profile switch, review that destination members will be enabled and all nonmembers disabled, including loose records and previously disabled destination members. Effects require triggers/conditions; this is not Cloud sync.</li></ol><p>Parameters such as <code>{{ params.giftName }}</code> resolve when applying a template. Runtime references such as <code>{{ event.user.uniqueId }}</code> remain for each event, while <a href="./variables.html">globals</a> provide shared saved values at execution.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Local template/profile import and export surfaces are available. Cloud browsing requires the corresponding host capability and account/service. A catalog preview is not evidence that an action&#39;s external service works. Missing plugins can leave imported definitions unusable until installed and configured.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For invalid JSON, use the reported parser errors and the expected document kind; renaming an arbitrary JSON file does not convert it. For a revision conflict, refresh the saved library before applying again. Retain the exported known-good profile and see <a href="./../preferences/backups.html">backups</a> for data that profile export does not include.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Manual template import first stores a catalog document; applying it creates linked actions/events. The parser defaults omitted <code>enabled</code> to true and application preserves those values. Manual profile import also prepares its entries for the owner review. Cloud catalog template import stores templates; Cloud profile import stages a profile mutation with source provenance. Neither origin nor a successful preview is a universal disabled-state guarantee. Inspect the final comparison and saved states. For CLI imports explicitly use <code>tiktools template import file.tiktemplate.json --disabled</code> or <code>tiktools template profile-import file.tikprofile.json --disabled</code>.</p><p>Switching profiles is an activation change: confirmation enables destination members and disables every nonmember action/event, including loose records. Previously disabled destination members may become enabled. Review both lists before confirming. Effects still require matching triggers, conditions and available runtime; the switch does not itself send a Cloud sync.</p>',15)])])}const h=a(r,[["render",s]]);export{m as __pageData,h as default};
